/*!
 * macOS Pure White — Minimalist + Full Box Shadow (Override Layer)
 * -----------------------------------------------------------------
 * Muat file ini SETELAH stylesheet asli (Bootstrap/Ubuntu).
 * Fokus: pure white, bebas border, bayangan penuh yang tegas.
 * -----------------------------------------------------------------
 */


/* ===================================================================
   1. ROOT VARIABLES & FONT
   =================================================================== */
:root {
  /* Palette — hanya putih & abu sangat lembut */
  --mac-bg:             #ffffff;
  --mac-bg-subtle:      #f8f8fa;
  --mac-bg-elevated:    #ffffff;
  --mac-border:         #f0f0f3;
  --mac-border-strong:  #e4e4e9;
  --mac-text:           #1d1d1f;
  --mac-text-secondary: #86868b;
  --mac-text-tertiary:  #aeaeb2;

  --mac-accent:         #0071e3;
  --mac-accent-hover:   #0077ed;
  --mac-accent-active:  #006edb;
  --mac-accent-soft:    rgba(0, 113, 227, 0.06);

  /* Radius */
  --mac-radius-xs:  6px;
  --mac-radius-sm:  10px;
  --mac-radius:     14px;
  --mac-radius-lg:  18px;
  --mac-radius-xl:  24px;
  --mac-radius-pill: 9999px;

  /* FULL BOX SHADOW — bayangan penuh, lapisan tegas */
  --mac-shadow-xs:  0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.04);
  --mac-shadow-sm:  0 3px 10px rgba(0, 0, 0, 0.07), 0 2px 4px rgba(0, 0, 0, 0.04);
  --mac-shadow-md:  0 10px 30px rgba(0, 0, 0, 0.10), 0 4px 8px rgba(0, 0, 0, 0.05);
  --mac-shadow-lg:  0 20px 50px rgba(0, 0, 0, 0.13), 0 8px 16px rgba(0, 0, 0, 0.06);
  --mac-shadow-xl:  0 30px 70px rgba(0, 0, 0, 0.16), 0 12px 24px rgba(0, 0, 0, 0.08);
  --mac-shadow-focus: 0 0 0 4px rgba(0, 113, 227, 0.14);

  --mac-font: -apple-system, BlinkMacSystemFont, "SF Pro Text",
              "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

html, body,
button, input, select, textarea,
.navbar, .table, .form-control,
h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 {
  font-family: "Inter", var(--mac-font) !important;
}

html, body {
  background-color: var(--mac-bg);
  color: var(--mac-text);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
body { font-size: 13px; line-height: 1.55; }

h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6 {
  font-weight: 600;
  color: var(--mac-text);
  letter-spacing: -0.02em;
}

/* ===================================================================
   2. LINK & FOCUS
   =================================================================== */
a { color: var(--mac-accent); }
a:hover, a:focus { color: var(--mac-accent-hover); text-decoration: none; }

.text-muted   { color: var(--mac-text-secondary) !important; }
.text-primary { color: var(--mac-accent) !important; }

a:focus,
.btn:focus, .btn:active:focus,
input:focus, select:focus, textarea:focus, .form-control:focus {
  outline: none !important;
  box-shadow: var(--mac-shadow-focus) !important;
}

/* ===================================================================
   3. BUTTONS — flat pure white, full shadow saat hover
   =================================================================== */
.btn {
  font-weight: 500;
  border: none;
  border-radius: var(--mac-radius-pill);
  background: #fff;
  color: var(--mac-text);
  box-shadow: var(--mac-shadow-sm);
  transition: box-shadow .18s ease, transform .1s ease, background-color .18s ease;
}
.btn:hover {
  box-shadow: var(--mac-shadow-md);
  background: #fff;
  color: var(--mac-text);
}
.btn:active { transform: translateY(1px); box-shadow: var(--mac-shadow-xs); }

.btn-primary {
  background: var(--mac-accent);
  color: #fff;
}
.btn-primary:hover, .btn-primary:focus { background: var(--mac-accent-hover); color: #fff; }
.btn-primary:active { background: var(--mac-accent-active); }

.btn-default { background: #fff; }
.btn-default:hover, .btn-default:focus { background: var(--mac-bg-subtle); }
.btn-success { background: #34c759; color: #fff; }
.btn-danger  { background: #ff453a; color: #fff; }
.btn-warning { background: #ff9f0a; color: #fff; }
.btn-info    { background: #64d2ff; color: #0b3d57; }
.btn-link { box-shadow: none; background: transparent; }
.btn-link:hover { box-shadow: none; }

/* ===================================================================
   4. NAVBAR — glass putih + shadow penuh
   =================================================================== */
.navbar {
  background: rgba(255, 255, 255, 0.85) !important;
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  backdrop-filter: saturate(180%) blur(20px);
  border: none !important;
  box-shadow: var(--mac-shadow-md);
}
.navbar-default { border-color: transparent !important; }
.navbar-default .navbar-brand,
.navbar-default .navbar-nav > li > a,
.navbar a, .navbar li { color: var(--mac-text) !important; }
.navbar-default .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > .active > a {
  color: var(--mac-accent) !important;
  background: var(--mac-accent-soft) !important;
  border-radius: var(--mac-radius-pill);
}
.navbar-inverse { background: #1d1d1f !important; box-shadow: var(--mac-shadow-md); }
.navbar-inverse .navbar-brand,
.navbar-inverse .navbar-nav > li > a { color: #f5f5f7 !important; }

.navbar .input-group {
  background: var(--mac-bg-subtle) !important;
  border-radius: var(--mac-radius-pill);
}

/* ===================================================================
   5. PANEL / CARD — pure white, tanpa border, FULL box shadow
   =================================================================== */
.panel,
.panel-default, .panel-primary, .panel-success,
.panel-info, .panel-warning, .panel-danger {
  background: var(--mac-bg-elevated);
  border: none !important;
  border-radius: var(--mac-radius-lg);
  box-shadow: var(--mac-shadow-md);
  overflow: hidden;
  transition: box-shadow .2s ease, transform .2s ease;
}
.panel:hover { box-shadow: var(--mac-shadow-lg); }

.panel-heading {
  background: transparent !important;
  border-bottom: none !important;
  font-weight: 600;
  padding: 16px 20px;
}
.panel-default > .panel-heading { color: var(--mac-text) !important; }
.panel-primary > .panel-heading { background: var(--mac-accent) !important; color: #fff !important; }
.panel-body { padding: 20px; }
.panel-footer {
  background: var(--mac-bg-subtle);
  border-top: none;
}

/* welcome cards */
.bs-welcome-item {
  border: none !important;
  border-radius: var(--mac-radius-lg);
  background: #fff !important;
  box-shadow: var(--mac-shadow-md);
  overflow: hidden;
  transition: box-shadow .2s ease, transform .2s ease;
}
.bs-welcome-item:hover { box-shadow: var(--mac-shadow-xl); transform: translateY(-3px); }
.bs-welcome-item .bs-welcome-header {
  background: var(--mac-bg-subtle) !important;
  color: var(--mac-text) !important;
  border: none !important;
}

/* dashboard boxes */
.r-box-left, .r-box-right {
  border: none !important;
  border-radius: var(--mac-radius-lg);
  background: #fff !important;
  box-shadow: var(--mac-shadow-md);
}

/* sidebar */
.r-vbar-page .r-left,
.r-leftbar-top-page > .r-under .r-left {
  background: #fff !important;
  border-right: none !important;
  box-shadow: var(--mac-shadow-md) !important;
}
.r-vbar-page .r-left .panel,
.r-leftbar-top-page > .r-under .r-left .panel {
  background: transparent !important;
  box-shadow: none !important;
}
.r-left .r-menu [data-menu-link]:hover {
  color: var(--mac-accent) !important;
  background: var(--mac-accent-soft) !important;
  border-radius: var(--mac-radius-pill);
}
.r-left .r-menu li.active.active.active > [data-menu-link] {
  background: var(--mac-accent) !important;
  border-radius: var(--mac-radius-pill);
  box-shadow: var(--mac-shadow-sm) !important;
}

/* ===================================================================
   6. TABLE — minimal, tanpa garis berlebih
   =================================================================== */
.table { background: #fff; }
.table > thead > tr > th {
  border-bottom: none !important;
  color: var(--mac-text-secondary);
  font-weight: 600;
  background: var(--mac-bg-subtle);
}
.table > tbody > tr > td,
.table > tbody > tr > th { border-top: none !important; }
.table-striped > tbody > tr:nth-of-type(odd) { background: var(--mac-bg-subtle); }
.table-hover > tbody > tr:hover { background: var(--mac-accent-soft); }
.table-bordered,
.table-bordered > thead > tr > th,
.table-bordered > tbody > tr > td { border: none !important; }

/* ===================================================================
   7. FORM
   =================================================================== */
.form-control {
  background: #fff;
  border: none;
  border-radius: var(--mac-radius-sm);
  box-shadow: var(--mac-shadow-xs);
  color: var(--mac-text);
}
.form-control:focus {
  border: none;
  box-shadow: var(--mac-shadow-focus), var(--mac-shadow-xs) !important;
}
.form-control::placeholder { color: var(--mac-text-tertiary); }

.input-group-addon {
  background: var(--mac-bg-subtle);
  border: none;
}
label { color: var(--mac-text); font-weight: 500; }

.has-error .form-control   { box-shadow: 0 0 0 4px rgba(255, 69, 58, 0.14) !important; }
.has-success .form-control { box-shadow: 0 0 0 4px rgba(52, 199, 89, 0.14) !important; }

/* ===================================================================
   8. DROPDOWN
   =================================================================== */
.dropdown-menu {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-lg);
  padding: 6px;
}
.dropdown-menu > li > a {
  border-radius: var(--mac-radius-sm);
  padding: 8px 12px;
  color: var(--mac-text);
}
.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus,
.dropdown-menu > .active > a {
  background: var(--mac-accent) !important;
  color: #fff !important;
}
.dropdown-menu .divider { background: var(--mac-border); margin: 6px 0; }

/* ===================================================================
   9. MODAL
   =================================================================== */
.modal-content {
  border: none;
  border-radius: var(--mac-radius-xl);
  box-shadow: var(--mac-shadow-xl);
}
.modal-header, .modal-footer { border: none; }
.modal-footer { background: var(--mac-bg-subtle); }
.modal-backdrop.in { opacity: 0.3; background: #000; }

/* ===================================================================
   10. ALERT / LABEL / BADGE
   =================================================================== */
.alert {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-xs);
}
.alert-success { background: #eafbee; color: #1e8e3e; }
.alert-info    { background: #e9f4ff; color: #0071e3; }
.alert-warning { background: #fff5e6; color: #b25000; }
.alert-danger  { background: #ffeceb; color: #d93025; }

.label { border-radius: var(--mac-radius-pill); font-weight: 600; }
.label-primary { background: var(--mac-accent); }
.badge { background: var(--mac-text-tertiary); border-radius: var(--mac-radius-pill); }

/* ===================================================================
   11. LIST GROUP / WELL / PAGINATION / PROGRESS
   =================================================================== */
.list-group {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-md);
}
.list-group-item { border: none; background: #fff; }
.list-group-item.active,
.list-group-item.active:hover {
  background: var(--mac-accent);
  border: none;
}

.well {
  background: var(--mac-bg-subtle);
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-xs);
}

.thumbnail {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-md);
}

.pagination > li > a, .pagination > li > span {
  border: none;
  color: var(--mac-accent);
  border-radius: var(--mac-radius-pill);
  margin: 0 3px;
  box-shadow: var(--mac-shadow-xs);
}
.pagination > .active > a {
  background: var(--mac-accent);
  color: #fff;
  box-shadow: var(--mac-shadow-sm);
}

.progress {
  background: var(--mac-bg-subtle);
  box-shadow: inset var(--mac-shadow-xs);
  border-radius: var(--mac-radius-pill);
}
.progress-bar { background: var(--mac-accent); box-shadow: none; }

/* ===================================================================
   12. BREADCRUMB / TOOLTIP / POPOVER
   =================================================================== */
.breadcrumb { background: transparent; color: var(--mac-text-secondary); }
.breadcrumb > .active { color: var(--mac-text); }

.tooltip-inner {
  background: rgba(29, 29, 31, 0.92);
  border-radius: var(--mac-radius-sm);
  padding: 6px 10px;
}
.popover {
  border: none;
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-lg);
}
.popover-title {
  background: var(--mac-bg-subtle);
  border-bottom: none;
}

/* ===================================================================
   13. NOTIFICATIONS / FILTER
   =================================================================== */
[data-itemtype="notifications"] > .dropdown-menu {
  border-radius: var(--mac-radius);
  box-shadow: var(--mac-shadow-lg);
}
[data-itemtype="notifications"] .r-noti-header { background: var(--mac-bg-subtle) !important; }
[data-itemtype="notifications"] .r-noti-message:hover { background: var(--mac-accent-soft) !important; }

.filterPanelContainer .filter-show-more,
.filterPanelContainer .filter-multiselect { background: var(--mac-bg-subtle) !important; }

/* ===================================================================
   14. SCROLLBAR
   =================================================================== */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.16);
  border-radius: 10px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover { background: rgba(0, 0, 0, 0.28); }

/* ===================================================================
   15. UTILITIES
   =================================================================== */
.hr, hr { border-top-color: var(--mac-border); }
.page-header { border-bottom: none; }

.bs-proceed-icon.bs-proceed-icon,
.bs-sidebarlogo a,
.r-vbar-page .r-left .navbar-brand,
.r-leftbar-top-page > .r-under .r-left .navbar-brand {
  color: var(--mac-accent) !important;
}
.navbar.navbar-default .btn-primary:not(:hover) {
  background: var(--mac-accent) !important;
  color: #fff !important;
}

